import ServiceCard from "../components/ServiceCard";
import "./Home.css";

export default function Home() {
  return (
    <div className="home">
      <header className="hero">
        <h1>Hire Trusted Professionals</h1>
        <p>Cleaning • Plumbing • AC Repair • Painting • Appliance Fix</p>
      </header>

      <section className="home-services">
        <h2>Popular Services</h2>

        <div className="service-list">
          <ServiceCard title="Home Cleaning" img="/clean.jpg" />
          <ServiceCard title="AC Repair" img="/ac.jpg" />
          <ServiceCard title="Plumbing" img="/plumb.jpg" />
          <ServiceCard title="Electrician" img="/electric.jpg" />
        </div>
      </section>
    </div>
  );
}
